// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette as C} from "../src/Roulette.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, uint256 blockNum, uint256 warpTime, address attacker) public {
        attacker = address(uint160(bound(uint256(uint160(attacker)), 0xffff + 1, type(uint160).max)));
        vm.assume(attacker.code.length == 0 && attacker != address(this) && attacker != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && attacker != 0x000000000000000000636F6e736F6c652e6c6f67 && attacker != 0x4e59b44847b379578588920cA78FbF26c0B4956C && attacker != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        amount = bound(amount, 10 ether, 10 ether);
        blockNum = bound(blockNum, 1, type(uint256).max);
        vm.roll(blockNum);
        warpTime = bound(warpTime, 1, type(uint64).max);
        vm.warp(warpTime);
        vm.assume(attacker != address(0) && attacker != address(this) && attacker != address(c));

        ReentrancyAttacker helper = new ReentrancyAttacker(c);
        vm.deal(attacker, 10 ether);

        vm.prank(attacker);
        try helper.attack{value: 10 ether}() {
            // call succeeded, now check property
        } catch {
            // if fallback reverts for legitimate reasons, property vacuously holds
            assertTrue(true);
            return;
        }

        if (blockNum % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == 10 ether);
        }
    }
}

contract ReentrancyAttacker {
    C target;
    bool locked;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        require(msg.value == 10 ether);
        (bool ok,) = address(target).call{value: 10 ether}("");
        require(ok);
    }

    receive() external payable {
        if (!locked && address(target).balance >= 10 ether && block.number % 15 == 0) {
            locked = true;
            (bool ok,) = address(target).call{value: 10 ether}("");
            locked = false;
        }
    }
}
